const $=s=>document.querySelector(s),toast=$('#toast'),authPanel=$('#auth-panel'),dashboard=$('#dashboard'),editor=$('#editor-modal');
let items=[],submissions=[],currentImage='',pendingImageBlob=null,previewObjectUrl='';
function notify(text){toast.textContent=text;toast.classList.add('show');clearTimeout(notify.t);notify.t=setTimeout(()=>toast.classList.remove('show'),3400)}
function esc(v=''){return String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function errorText(error,fallback='Terjadi kesalahan.'){return error?.message||fallback}
function setButtonBusy(button,busy,label){if(!button.dataset.label)button.dataset.label=button.innerHTML;button.disabled=busy;button.innerHTML=busy?label:button.dataset.label}
async function openDashboard(){authPanel.hidden=true;dashboard.hidden=false;await Promise.all([loadMods(),loadSubmissions(),loadRecentOnline()])}
async function loadMods(){try{items=await NMData.get();renderAdmin()}catch(error){notify(errorText(error,'Katalog gagal dimuat.'))}}
async function loadSubmissions(){try{submissions=await NMData.getSubmissions();renderSubmissions()}catch(error){notify(errorText(error,'Pengajuan gagal dimuat.'))}}
async function loadRecentOnline(){try{$('#admin-online').textContent=await NMData.getRecentVisitorCount(120)}catch(error){$('#admin-online').textContent='—';console.warn(error.message)}}

$('#auth-form').addEventListener('submit',async e=>{e.preventDefault();const button=$('#auth-submit');setButtonBusy(button,true,'Memeriksa akun…');try{await NMData.signIn($('#admin-username').value.trim(),$('#admin-password').value);$('#admin-password').value='';await openDashboard();notify(`Selamat datang, ${NMData.adminUsername}.`)}catch(error){notify(errorText(error,'Username atau password salah.'))}finally{setButtonBusy(button,false)}});

function thumb(x){return x.image?`style="background-image:url('${esc(x.image).replace(/'/g,'%27')}')"`:''}
function row(x){return `<div class="admin-row"><button class="admin-item-name" data-preview="${x.id}" title="Lihat tampilan detail"><span class="admin-thumb ${NMData.coverClass(x.category)}" ${thumb(x)}></span><div><b>${esc(x.title)}</b><small>${esc(x.creator||'Tanpa kredit')} · ${esc(x.category)} · ${esc(x.version)}</small></div></button><div class="admin-cell">${esc(x.platform)}<small>${esc(x.size)}</small></div><div class="admin-cell"><span class="status-pill ${x.active?'':'off'}">${x.active?'Aktif':'Draft'}</span></div><div class="admin-cell">${Number(x.clicks||0)}<small>Klik</small></div><div class="row-actions"><button data-preview="${x.id}">Preview</button><button data-edit="${x.id}">Sunting</button><button class="delete" data-delete="${x.id}">Hapus</button></div></div>`}
function renderAdmin(){const q=$('#admin-search').value.toLowerCase(),shown=items.filter(x=>x.title.toLowerCase().includes(q));$('#admin-list').innerHTML=shown.length?shown.map(row).join(''):'<div class="empty-state"><h3>Belum ada mod</h3><p>Tambahkan mod baru atau pulihkan data contoh.</p></div>';$('#admin-total').textContent=items.length;$('#admin-active').textContent=items.filter(x=>x.active).length}
function updateImagePreview(src=currentImage){const preview=$('#image-preview');preview.style.backgroundImage=src?`url("${String(src).replace(/"/g,'%22')}")`:'';preview.classList.toggle('has-image',Boolean(src));preview.innerHTML=src?'':'<span>Preview gambar 16:10</span>'}
function revokePreview(){if(previewObjectUrl){URL.revokeObjectURL(previewObjectUrl);previewObjectUrl=''}}
function downloadLinkRow(link={}){return `<div class="additional-link-row"><label>Nama mod / file<input class="additional-link-label" maxlength="80" required value="${esc(link.label||'')}" placeholder="Contoh: Texture Pack"></label><label>URL download<input class="additional-link-url" type="url" required value="${esc(link.url||'')}" placeholder="https://..."></label><button type="button" data-remove-download-link aria-label="Hapus link">×</button></div>`}
function renderDownloadLinks(links=[]){$('#additional-download-links').innerHTML=(links||[]).map(downloadLinkRow).join('')}
function collectDownloadLinks(){return[...document.querySelectorAll('.additional-link-row')].map(row=>({label:row.querySelector('.additional-link-label').value.trim(),url:row.querySelector('.additional-link-url').value.trim()})).filter(link=>link.label&&link.url)}
function openEditor(id,preset){const x=preset||items.find(i=>i.id===id);revokePreview();pendingImageBlob=null;$('#editor-title').textContent=id?'Sunting mod':preset?'Tinjau pengajuan':'Tambah mod';$('#item-id').value=id||'';$('#item-title').value=x?.title||'';$('#item-creator').value=x?.creator||'';$('#item-category').value=x?.category||'Adventure';$('#item-platform').value=x?.platform||'PC';$('#item-version').value=x?.version||'v1.0';$('#item-size').value=x?.size||'';$('#item-description').value=x?.description||'';$('#item-details').value=x?.details||'';$('#item-link').value=x?.link||'';renderDownloadLinks(x?.downloadLinks);$('#item-youtube').value=x?.youtube||'';$('#item-image-url').value=x?.image?.startsWith('http')?x.image:'';$('#item-image-file').value='';$('#item-active').checked=x?.active??true;currentImage=x?.image||'';updateImagePreview();editor.showModal()}
function cropImage(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error('File tidak dapat dibaca.'));reader.onload=()=>{const img=new Image();img.onerror=()=>reject(new Error('Format gambar tidak didukung.'));img.onload=()=>{const ratio=16/10,source=img.width/img.height;let sx=0,sy=0,sw=img.width,sh=img.height;if(source>ratio){sw=img.height*ratio;sx=(img.width-sw)/2}else{sh=img.width/ratio;sy=(img.height-sh)/2}const canvas=document.createElement('canvas');canvas.width=1280;canvas.height=800;canvas.getContext('2d').drawImage(img,sx,sy,sw,sh,0,0,1280,800);canvas.toBlob(blob=>blob?resolve(blob):reject(new Error('Gambar gagal diproses.')),'image/webp',.82)};img.src=reader.result};reader.readAsDataURL(file)})}
$('#item-image-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024){e.target.value='';return notify('Ukuran gambar maksimal 10 MB.')}notify('Memotong gambar ke rasio 16:10…');try{pendingImageBlob=await cropImage(file);revokePreview();previewObjectUrl=URL.createObjectURL(pendingImageBlob);currentImage=previewObjectUrl;$('#item-image-url').value='';updateImagePreview();notify('Gambar siap diunggah.')}catch(error){notify(errorText(error))}});
$('#item-image-url').addEventListener('input',e=>{pendingImageBlob=null;revokePreview();currentImage=e.target.value.trim();updateImagePreview()});
$('#add-download-link').addEventListener('click',()=>{const list=$('#additional-download-links');if(list.children.length>=20)return notify('Maksimal 20 link tambahan.');list.insertAdjacentHTML('beforeend',downloadLinkRow());list.lastElementChild.querySelector('input').focus()});
$('#additional-download-links').addEventListener('click',e=>{const button=e.target.closest('[data-remove-download-link]');if(button)button.closest('.additional-link-row').remove()});

$('#admin-list').addEventListener('click',async e=>{const preview=e.target.closest('[data-preview]'),edit=e.target.closest('[data-edit]'),del=e.target.closest('[data-delete]');if(preview){window.open(`${NMData.detailUrl(preview.dataset.preview)}&preview=1`,'_blank','noopener');return}if(edit){openEditor(edit.dataset.edit);return}if(del&&confirm('Hapus item ini dari katalog online?')){try{await NMData.remove(del.dataset.delete);await loadMods();notify('Item berhasil dihapus.')}catch(error){notify(errorText(error,'Item gagal dihapus.'))}}});
$('#editor-form').addEventListener('submit',async e=>{e.preventDefault();const button=e.submitter,id=$('#item-id').value||`nm-${Date.now()}`,old=items.find(x=>x.id===id);setButtonBusy(button,true,'Menyimpan…');try{let image=currentImage;if(pendingImageBlob){notify('Mengunggah gambar…');image=await NMData.uploadImage(pendingImageBlob,id)}const value={id,title:$('#item-title').value.trim(),creator:$('#item-creator').value.trim(),category:$('#item-category').value,platform:$('#item-platform').value,version:$('#item-version').value.trim(),size:$('#item-size').value.trim(),description:$('#item-description').value.trim(),details:$('#item-details').value.trim(),image,youtube:$('#item-youtube').value.trim(),link:$('#item-link').value.trim(),downloadLinks:collectDownloadLinks(),active:$('#item-active').checked,rating:old?.rating||0,clicks:old?.clicks||0};await NMData.upsert(value);editor.close();revokePreview();await loadMods();notify('Mod berhasil disimpan ke database online.')}catch(error){notify(errorText(error,'Mod gagal disimpan.'))}finally{setButtonBusy(button,false)}});

function submissionCard(s){const label=s.status==='pending'?'Menunggu':s.status==='approved'?'Sudah jadi draft':'Ditolak';return `<article class="submission-card"><div class="submission-top"><div><span class="status-pill ${s.status!=='pending'?'off':''}">${label}</span><h3>${esc(s.title)}</h3><p>Oleh <b>${esc(s.creator)}</b> · ${esc(s.game||'Game tidak disebut')}</p></div><time>${new Date(s.submittedAt).toLocaleDateString('id-ID')}</time></div><p>${esc(s.description)}</p><div class="submission-meta"><span>${esc(s.platform)}</span><span>${esc(s.version)}</span><span>${esc(s.size||'-')}</span></div>${s.status==='pending'?`<div class="submission-actions"><button class="button primary" data-draft="${s.id}">Jadikan draft</button><button class="button ghost" data-close-submission="${s.id}">Tolak pengajuan</button></div>`:''}</article>`}
function renderSubmissions(){const pending=submissions.filter(x=>x.status==='pending');$('#submission-list').innerHTML=submissions.length?submissions.map(submissionCard).join(''):'<div class="empty-submissions"><span>✓</span><h3>Belum ada pengajuan</h3><p>Pengajuan dari halaman publik akan muncul di sini.</p></div>';$('#submission-badge').textContent=pending.length;$('#admin-pending').textContent=pending.length;document.title=pending.length?`(${pending.length}) Admin — Nusantara Mod`:'Admin — Nusantara Mod'}
$('#submission-list').addEventListener('click',async e=>{const draft=e.target.closest('[data-draft]'),close=e.target.closest('[data-close-submission]');try{if(draft){const s=submissions.find(x=>x.id===draft.dataset.draft);if(!s)return;const mod={id:`nm-${Date.now()}`,title:s.title,creator:s.creator,category:s.category,platform:s.platform,version:s.version,size:s.size,description:s.description,image:s.image,youtube:s.youtube,link:s.link,active:false,rating:0,clicks:0};await NMData.upsert(mod);await NMData.updateSubmission(s.id,{status:'approved'});await Promise.all([loadMods(),loadSubmissions()]);openEditor(mod.id);notify('Pengajuan menjadi draft. Periksa lalu aktifkan saat siap.');return}if(close){await NMData.updateSubmission(close.dataset.closeSubmission,{status:'rejected'});await loadSubmissions();notify('Pengajuan ditolak.')}}catch(error){notify(errorText(error,'Status pengajuan gagal diperbarui.'))}});

$('#add-item').addEventListener('click',()=>openEditor());
$('#admin-search').addEventListener('input',renderAdmin);
$('#logout').addEventListener('click',async()=>{await NMData.signOut();location.reload()});
$('#reset-data').addEventListener('click',async()=>{if(!confirm('Tambahkan atau pulihkan data contoh ke database online?'))return;try{await NMData.reset();await loadMods();notify('Data contoh berhasil ditambahkan.')}catch(error){notify(errorText(error,'Data contoh gagal ditambahkan.'))}});
editor.addEventListener('click',e=>{if(e.target===editor||e.target.closest('.modal-close')){editor.close();revokePreview()}});

(async()=>{try{if(await NMData.isAdmin())await openDashboard()}catch(error){notify(errorText(error,'Sesi admin gagal diperiksa.'))}})();
setInterval(()=>{if(!dashboard.hidden)loadRecentOnline()},60*1000);
